import 'dart:typed_data';

/// A local launch request. Templates are generated by the native format engine.
class EditorLaunch {
  const EditorLaunch({
    this.bytes,
    this.name,
    this.create = false,
    this.template = false,
  });
  final Uint8List? bytes;
  final String? name;
  final bool create;
  final bool template;
}

typedef RememberFile = Future<void> Function(Uint8List bytes, String filename);
